INSERT INTO tips VALUES(1,'tibialis_anterior','daily','action','Toe raises: 3x15 reps','Stand flat, lift toes off the ground keeping heels planted. Hold 2s at the top. Do 3 sets of 15 reps to strengthen the tibialis anterior directly.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(2,'tibialis_anterior','daily','action','Wall toe raises: 3x12 reps','Lean back against a wall with feet 30cm out. Lift toes toward shins, hold 3s. This isolates the tibialis anterior under load.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(3,'tibialis_anterior','daily','action','Eccentric toe lowers: 3x10','Raise toes fully, then lower them as slowly as possible over 4-5 seconds. Eccentric loading builds tendon resilience more effectively than concentric alone.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(4,'tibialis_anterior','post_run','action','Tib anterior self-massage: 2 min','Use your thumb or a massage stick along the outer shin from knee to ankle. Apply moderate pressure for 2 minutes per leg to reduce post-run tightness.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(5,'tibialis_anterior','daily','action','Resistance band dorsiflexion: 3x15','Loop a band around your forefoot anchored behind you. Pull toes toward your shin against resistance. 3 sets of 15 reps per foot builds tibialis anterior endurance.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(6,'tibialis_anterior','daily','action','Heel walks: 3x20m','Walk on your heels with toes lifted off the ground for 20 meters. Repeat 3 times. This is a functional tibialis anterior strengthener used in sports rehab.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(7,'tibialis_anterior','post_run','action','Kneeling tib stretch: 30s each','Kneel with tops of feet flat on the floor. Gently lean back to stretch the tibialis anterior. Hold 30 seconds per side, repeat twice.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(8,'tibialis_anterior','recovery_day','action','Tib anterior foam roll: 2 min','Kneel over a foam roller placed under your shins. Roll slowly from below the knee to the ankle for 2 minutes. Pause on tender spots for 10 seconds.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(9,'tibialis_anterior','daily','action','Seated toe taps: 3x30s','Sit with feet flat on the floor. Tap your toes rapidly for 30 seconds, rest 15 seconds. Repeat 3 times. Builds tibialis anterior endurance for long runs.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(10,'tibialis_anterior','daily','info','Ankle circles: 20 each direction','Rotate your ankle slowly through full range of motion. 20 circles clockwise, 20 counterclockwise per foot. Maintains tibialis anterior flexibility and joint health.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(11,'tibialis_anterior','post_long_run','warning','Ice shin if sore: 15 min max','If your tibialis anterior feels tight or sore after a long run, apply ice wrapped in a cloth for 10-15 minutes. Do not ice directly on skin or exceed 15 minutes.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(12,'tibialis_anterior','high_load_week','warning','Monitor shin tightness closely','High-volume weeks stress the tibialis anterior. If you feel a dull ache along the outer shin during runs, reduce pace immediately and shorten the run by 20%.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(13,'tibialis_anterior','daily','action','Single-leg toe raise: 3x10 each','Balance on one foot and raise your toes 10 times. This corrects side-to-side imbalances in the tibialis anterior that lead to overuse injuries.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(14,'tibialis_anterior','post_run','action','Dorsiflexion stretch: hold 30s','Step one foot back, press the top of your rear foot into the ground and gently push your ankle down. Hold 30 seconds each side to lengthen the tibialis anterior.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(15,'tibialis_anterior','daily','action','Tib raise off step: 3x12','Stand with your heels on a step edge, toes hanging off. Lift toes up toward shins, hold 2s, lower slowly. The increased range of motion strengthens through full dorsiflexion.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(16,'tibialis_anterior','rest_day','action','Barefoot walking: 10 min','Walk barefoot on a flat surface for 10 minutes. Barefoot walking activates intrinsic foot muscles and the tibialis anterior in a natural gait pattern.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(17,'tibialis_anterior','post_hard_run','warning','Ease off if shins burn post-run','A burning sensation in the front of the shin after hard efforts is a tibialis anterior overload signal. Take the next run easy and add 5 extra minutes of stretching.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(18,'tibialis_anterior','daily','info','Check shoe drop height','Shoes with a drop over 10mm shift load away from the tibialis anterior. If rehabbing, a moderate 6-8mm drop balances calf and shin muscle recruitment.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(19,'tibialis_anterior','daily','action','Alphabet ankles: A-Z each foot','Trace the alphabet in the air with your toes, one foot at a time. This moves the tibialis anterior through every angle of motion and takes about 90 seconds per foot.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(20,'tibialis_anterior','post_run','action','Compression socks for 2h post-run','Wear calf compression socks for 2 hours after running. Studies show they reduce shin soreness by improving venous return and reducing tibialis anterior swelling.','British Journal of Sports Medicine, 2017',0.0,999.0,1);
INSERT INTO tips VALUES(21,'tibialis_anterior','daily','action','Isometric tib hold: 3x20s','Raise your toes fully and hold at the top for 20 seconds. Repeat 3 times per foot. Isometric holds build tendon stiffness critical for tibialis anterior health.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(22,'tibialis_anterior','recovery_day','action','Lacrosse ball on outer shin: 90s','Sit with one leg crossed. Roll a lacrosse ball along the outer shin muscle belly for 90 seconds. Apply enough pressure to feel release but not sharp pain.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(23,'tibialis_anterior','daily','info','Warm up shins before running','Do 20 toe raises and 10 ankle circles per foot before every run. Cold tibialis anterior muscles are more prone to strain during the first kilometer.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(24,'tibialis_anterior','high_load_week','action','Add a tib anterior session today','During high-volume weeks, do an extra 5-minute tibialis anterior circuit: 15 toe raises, 10 heel walks per side, 10 band dorsiflexions. Prevention beats treatment.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(25,'tibialis_anterior','daily','action','Banded ankle inversion: 3x12','Anchor a band to a fixed point at foot level. Loop it around your forefoot and turn your sole inward against the resistance. 3x12 reps strengthens the tib anterior''s inversion role.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(26,'tibialis_anterior','post_long_run','action','Elevate legs for 15 min post-run','Lie on your back with legs up against a wall for 15 minutes after your long run. Reduces shin swelling and accelerates tibialis anterior recovery.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(27,'tibialis_anterior','daily','info','Avoid sudden mileage spikes','The tibialis anterior is one of the first muscles to overload from rapid volume increases. Keep weekly mileage increases under 10% when building back from shin issues.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(28,'tibialis_anterior','post_run','action','Tibial nerve glide: 10 reps','Sit with one leg extended. Point your toes, then flex your foot while extending your neck back. Repeat 10 times per leg. Nerve glides reduce tibialis anterior tension from neural tightness.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(29,'tibialis_anterior','daily','action','Weighted toe raises: 3x12','Hold a dumbbell (3-5kg) at your side and perform toe raises. Adding progressive load strengthens the tibialis anterior beyond bodyweight adaptation.',NULL,30.0,999.0,1);
INSERT INTO tips VALUES(30,'tibialis_anterior','rest_day','info','Tib recovery: contrast therapy','Alternate 1 minute warm water and 30 seconds cold water on your shins for 5 cycles. Contrast therapy promotes blood flow to the tibialis anterior on rest days.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(31,'tibialis_anterior','daily','action','Slow heel-to-toe walk: 2x20m','Walk exaggeratedly slow, rolling from heel to toe over 20 meters. This forces the tibialis anterior to control dorsiflexion through each stride. Repeat twice.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(32,'tibialis_anterior','post_hard_run','action','Gentle tib stretch: 4x20s','After hard runs, gently stretch the tibialis anterior by pointing your toes and pressing the top of your foot down. Hold 20 seconds, repeat 4 times. Never bounce.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(33,'recovery','post_run','action','Walk 5 min after every run','A 5-minute cool-down walk brings your heart rate down gradually and helps clear lactate from the legs. Never stop abruptly after a run.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(34,'recovery','post_long_run','action','Refuel within 30 min of long run','Eat 1.0-1.2g carbs per kg bodyweight plus 20-25g protein within 30 minutes of finishing. The glycogen replenishment window is most effective in the first hour.','ACSM Position Stand on Nutrition and Performance',0.0,999.0,1);
INSERT INTO tips VALUES(35,'recovery','recovery_day','info','Active recovery: 20 min walk','On recovery days, a 20-minute easy walk promotes blood flow without adding training stress. Avoid sitting for more than 90 minutes at a time.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(36,'recovery','post_run','action','Static stretch: hold 30s each','After running, hold each stretch for at least 30 seconds: quads, hamstrings, calves, hip flexors, and glutes. Static stretching post-run reduces next-day soreness.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(37,'recovery','recovery_day','action','Foam roll major muscle groups','Spend 2 minutes per muscle group: quads, IT band, calves, glutes, and hamstrings. Roll slowly and pause on tight spots for 10-15 seconds.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(38,'recovery','post_hard_run','action','Contrast shower: 3 cycles','Alternate 1 minute hot and 30 seconds cold water for 3 cycles, ending on cold. Contrast showers reduce inflammation and perceived muscle soreness after hard efforts.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(39,'recovery','post_long_run','warning','Next run: easy pace only','The run after a long run should always be at easy conversational pace. Your muscles need 48-72 hours to fully recover glycogen stores after runs exceeding 15km.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(40,'recovery','high_load_week','warning','Schedule at least 2 rest days','During high-volume weeks, ensure at least 2 full rest days. Adaptation happens during recovery, not during training. More is not always better.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(41,'recovery','daily','info','Track morning resting heart rate','Measure resting heart rate upon waking before getting out of bed. An increase of 5+ bpm over your baseline indicates incomplete recovery. Take an easy day.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(42,'recovery','recovery_day','action','Epsom salt bath: 15-20 min','Add 300g of Epsom salts to a warm bath and soak for 15-20 minutes. Magnesium absorption through skin helps relax muscles and may reduce soreness.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(43,'recovery','post_run','info','Hydrate: 500ml within 30 min','Drink at least 500ml of water within 30 minutes of finishing your run. Add a pinch of salt if the run was over 60 minutes or in warm conditions.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(44,'recovery','daily','info','Avoid hard sessions back-to-back','Never schedule two hard efforts on consecutive days. Allow at least 48 hours between tempo runs, intervals, or long runs to prevent overtraining.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(45,'recovery','recovery_day','action','Gentle yoga flow: 20 min','A 20-minute gentle yoga session on recovery days improves flexibility, reduces muscle tension, and activates the parasympathetic nervous system for better recovery.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(46,'recovery','post_long_run','action','Legs up the wall: 10 min','Lie on your back with legs elevated against a wall for 10 minutes post-long-run. This reduces lower leg swelling and promotes venous return.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(47,'recovery','rest_day','info','Rest day is a training day','Adaptation happens during rest, not during effort. A true rest day with good nutrition and sleep makes your next hard session stronger. Do not feel guilty.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(48,'recovery','high_load_week','action','Add 10 min of self-massage','During high-volume weeks, spend 10 minutes with a massage gun or foam roller each evening. Focus on calves, quads, and shins to prevent accumulated tightness.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(49,'recovery','post_run','action','Protein shake within 1 hour','Consume 20-30g of protein within 1 hour of running to support muscle repair. Whey protein or a glass of milk with a banana is sufficient.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(50,'recovery','daily','info','Compression tights: 12-24h post','Wearing compression tights for 12-24 hours after hard training reduces muscle oscillation damage and perceived soreness, especially after long runs.','Journal of Strength and Conditioning Research, 2016',0.0,999.0,1);
INSERT INTO tips VALUES(51,'recovery','recovery_day','action','Swimming: 20 min easy laps','Easy swimming provides active recovery without impact stress. The water pressure acts as compression and the horizontal position promotes blood flow to legs.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(52,'recovery','post_hard_run','action','Cold water immersion: 10 min','Soak legs in cold water (10-15 degrees C) for 10 minutes after hard efforts. Cold immersion reduces inflammation and accelerates recovery between sessions.','Cochrane Review on Cold Water Immersion, 2012',0.0,999.0,1);
INSERT INTO tips VALUES(53,'recovery','daily','info','Deload week every 4th week','Reduce volume by 30-40% every 4th week to allow cumulative fatigue to dissipate. Consistent deload cycles prevent overtraining and maintain long-term progression.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(54,'nutrition','daily','info','Eat 1.4-1.7g protein per kg/day','Endurance runners need 1.4-1.7g of protein per kilogram of bodyweight daily. Spread intake across 4-5 meals for optimal muscle protein synthesis.','ISSN Position Stand on Protein, 2017',0.0,999.0,1);
INSERT INTO tips VALUES(55,'nutrition','post_long_run','action','Carb reload: 8-10g/kg today','After long runs over 90 minutes, aim for 8-10g carbohydrates per kg bodyweight throughout the rest of the day. Rice, pasta, potatoes, and fruit are ideal sources.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(56,'nutrition','daily','info','Iron-rich foods 3x per week','Runners lose iron through sweat and foot-strike hemolysis. Eat red meat, lentils, or spinach paired with vitamin C at least 3 times per week to maintain stores.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(57,'nutrition','daily','action','Pre-run meal: 2-3h before','Eat a carb-rich meal 2-3 hours before running. Good options: oatmeal with banana, toast with honey, or rice with light protein. Avoid high fat and fiber close to running.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(58,'nutrition','post_run','action','Recovery smoothie: carbs + protein','Blend 1 banana, 200ml milk, 1 scoop protein powder, and a handful of berries. This provides the 3:1 carb-to-protein ratio optimal for post-run recovery.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(59,'nutrition','daily','info','Hydration: 35ml per kg bodyweight','Drink at least 35ml of water per kilogram of bodyweight daily. Add 500-750ml for every hour of running. Check urine color: pale yellow means well hydrated.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(60,'nutrition','post_long_run','action','Electrolytes after 90+ min runs','Runs over 90 minutes deplete sodium, potassium, and magnesium. Take an electrolyte tablet or drink with at least 500mg sodium per liter within 30 minutes of finishing.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(61,'nutrition','daily','info','Omega-3: anti-inflammatory support','Consume omega-3 fatty acids through oily fish twice per week or supplement with 1-2g EPA/DHA daily. Omega-3s reduce exercise-induced inflammation and joint stiffness.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(62,'nutrition','daily','info','Vitamin D: check your levels','Runners training in northern latitudes often have low vitamin D. Supplement 1000-2000 IU daily in winter months. Vitamin D supports bone density and immune function.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(63,'nutrition','high_load_week','action','Increase carbs during build weeks','During high-volume build weeks, increase daily carbohydrate intake to 6-8g per kg bodyweight. Underfueling during hard training blocks leads to breakdown, not adaptation.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(64,'nutrition','daily','info','Magnesium: 400mg daily','Magnesium supports muscle relaxation and sleep quality. Aim for 400mg daily from foods (dark chocolate, nuts, leafy greens) or supplements taken in the evening.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(65,'nutrition','post_run','info','Tart cherry juice: reduce soreness','Drinking 250ml of tart cherry juice post-run has been shown to reduce muscle soreness and inflammation markers. Effective before and after hard training days.','Scandinavian Journal of Medicine & Science in Sports, 2010',0.0,999.0,1);
INSERT INTO tips VALUES(66,'nutrition','daily','warning','Avoid training on empty stomach','Fasted running for longer than 45 minutes increases cortisol and muscle breakdown. Eat at least a banana or energy bar before morning runs exceeding 45 minutes.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(67,'nutrition','recovery_day','info','Recovery day: keep protein high','Muscle repair peaks 24-48 hours after hard training. Maintain high protein intake on recovery days: 25-30g per meal across 4 meals to support tissue repair.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(68,'nutrition','daily','info','Caffeine: 3-6mg/kg before runs','Caffeine improves endurance performance by 2-4%. Take 3-6mg per kg bodyweight 30-60 minutes before key sessions. Avoid after 2pm to protect sleep quality.','ISSN Position Stand on Caffeine, 2021',0.0,999.0,1);
INSERT INTO tips VALUES(69,'nutrition','post_long_run','action','Eat within the glycogen window','Glycogen synthase enzyme activity peaks in the first 30 minutes post-exercise. Eating carbs during this window replenishes stores 50% faster than waiting 2 hours.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(70,'sleep','daily','info','Target 7.5-9 hours of sleep','Runners need 7.5-9 hours of sleep for optimal recovery and performance. Growth hormone release peaks during deep sleep in the first 3-4 hours of the night.','Sleep Foundation Guidelines for Athletes',0.0,999.0,1);
INSERT INTO tips VALUES(71,'sleep','daily','action','Consistent bedtime: same time daily','Go to bed within 30 minutes of the same time every night, including weekends. Consistent circadian rhythm improves sleep quality more than total sleep duration.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(72,'sleep','daily','info','No screens 60 min before bed','Blue light from screens suppresses melatonin production by up to 50%. Switch to a book, stretching, or meditation 60 minutes before your target bedtime.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(73,'sleep','daily','action','Cool bedroom: 18-19 degrees C','Core body temperature must drop for sleep onset. Keep your bedroom at 18-19 degrees C. A too-warm room delays sleep onset and reduces deep sleep duration.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(74,'sleep','post_hard_run','info','Extra 30 min sleep after hard days','After hard training sessions, aim for an extra 30 minutes of sleep. Hard efforts increase inflammation and muscle damage that require additional sleep-based recovery.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(75,'sleep','daily','warning','No caffeine after 2pm','Caffeine has a half-life of 5-6 hours. Coffee at 2pm means half the caffeine is still active at 8pm, reducing deep sleep quality even if you fall asleep on time.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(76,'sleep','high_load_week','action','Prioritize sleep during build weeks','High-volume training demands more recovery. Add 30-60 extra minutes of sleep during build weeks. Sleep debt accumulated during hard training blocks limits adaptation.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(77,'sleep','daily','info','Morning sunlight: 10 min outside','Get 10 minutes of natural sunlight within 1 hour of waking. Morning light exposure sets your circadian clock and improves both alertness and evening sleep onset.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(78,'sleep','daily','action','Pre-sleep routine: 15 min wind-down','Create a consistent 15-minute pre-sleep routine: dim lights, light stretching or breathing exercises, and avoid stimulating content. Routines signal your brain to prepare for sleep.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(79,'sleep','recovery_day','info','Nap 20-30 min max on rest days','A 20-30 minute nap between 1-3pm can restore alertness without affecting nighttime sleep. Avoid naps longer than 30 minutes as they cause sleep inertia and may disrupt your night.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(80,'sleep','daily','info','Magnesium glycinate before bed','Take 200-400mg magnesium glycinate 30-60 minutes before bed. This form crosses the blood-brain barrier and promotes muscle relaxation and sleep quality.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(81,'sleep','daily','warning','Alcohol disrupts deep sleep','Even 1-2 drinks reduce REM and deep sleep by 20-40%. Avoid alcohol within 3 hours of bedtime, especially during build weeks when recovery demands are highest.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(82,'sleep','post_long_run','action','Sleep 8+ hours after long runs','Long runs deplete glycogen and create micro-damage. Sleep at least 8 hours the night after your long run. Consider going to bed 30 minutes earlier than usual.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(83,'mobility','daily','action','Hip flexor stretch: 2x30s each','Kneel in a lunge position, push hips forward until you feel a stretch in the front of your rear hip. Hold 30 seconds per side, twice. Tight hip flexors alter running gait.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(84,'mobility','post_run','action','Calf stretch: 3x30s each side','Place hands on a wall, step one foot back with heel flat. Lean forward to stretch the gastrocnemius for 30 seconds. Then bend the rear knee slightly for the soleus. 3 sets each.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(85,'mobility','daily','action','Ankle dorsiflexion mobilization','In a half-kneeling position, push your front knee over your toes while keeping the heel down. Hold 5 seconds, return. Do 15 reps per side. Targets the ankle joint critical for running mechanics.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(86,'mobility','daily','action','90/90 hip rotation: 10 reps','Sit with both legs at 90-degree angles. Rotate from one side to the other, keeping your back tall. Do 10 controlled transitions. This opens internal and external hip rotation.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(87,'mobility','recovery_day','action','Full body mobility: 15 min','Spend 15 minutes working through ankles, hips, thoracic spine, and shoulders. Cat-cow, world''s greatest stretch, and leg swings make a complete runner''s mobility routine.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(88,'mobility','post_run','action','Pigeon pose: 60s each side','From a plank position, bring one knee forward and lower your hips. Hold for 60 seconds per side. Pigeon pose releases the deep hip rotators that tighten from running.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(89,'mobility','daily','action','Thoracic spine rotation: 10 each','Lie on your side with knees stacked and bent. Open your top arm across your body, following with your eyes. 10 rotations each side. Running requires torso rotation that tight T-spines limit.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(90,'mobility','post_long_run','action','Hamstring stretch: PNF 3x20s','Lie on your back, leg raised with a band. Stretch for 5 seconds, push against the band for 5 seconds, then stretch deeper for 20 seconds. PNF stretching gains range faster than static alone.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(91,'mobility','daily','info','Dynamic warm-up before every run','Replace static stretching before runs with dynamic movements: leg swings (10 each direction), high knees (20), butt kicks (20), and walking lunges (10). Takes 3 minutes.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(92,'mobility','rest_day','action','Couch stretch: 2 min each side','Place one knee against a wall with your shin vertical, other foot forward in a lunge. Hold for 2 minutes per side. This aggressively opens the hip flexors and quads.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(93,'mobility','daily','action','Foot and toe mobilization: 3 min','Spread your toes wide, then curl them tight. Repeat 15 times. Roll a golf ball under each foot for 60 seconds. Strong, mobile feet reduce compensatory tibialis anterior strain.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(94,'mobility','post_run','action','IT band foam roll: 2 min each leg','Lie on your side with the foam roller under your outer thigh. Roll from hip to just above the knee for 2 minutes per leg. IT band tightness alters knee tracking and shin mechanics.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(95,'mobility','daily','info','Sit less: stand up every 45 min','Prolonged sitting tightens hip flexors and weakens glutes. Set a timer to stand and move for 2 minutes every 45 minutes. This preserves the mobility gains from your stretching.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(96,'mobility','recovery_day','action','Adductor stretch: 3x30s','Stand wide, shift weight to one side and bend that knee while keeping the other leg straight. Hold 30 seconds per side, 3 rounds. Inner thigh tightness affects hip stability during running.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(97,'mobility','post_hard_run','action','Quad stretch with hip tilt: 30s','Stand on one foot, pull the other heel to your glute, then tilt your pelvis under (posterior tilt). Hold 30 seconds per side. The pelvic tilt deepens the quad and hip flexor stretch.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(98,'mobility','daily','action','Glute bridge with hold: 3x10','Lie on your back, feet flat, push hips up and squeeze glutes at the top for 3 seconds. 3 sets of 10 reps. Bridges activate glutes and improve hip extension mobility simultaneously.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(99,'strength','daily','action','Single-leg calf raise: 3x15','Stand on one foot on a step edge. Rise up fully, lower slowly below the step level. 3x15 per leg. Calf strength directly reduces tibialis anterior overload by balancing shin and calf forces.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(100,'strength','daily','action','Single-leg squats: 3x10 each','Stand on one leg, lower into a partial squat keeping your knee tracking over your toes. 3 sets of 10 per leg. Single-leg strength prevents gait asymmetries that overload the tibialis anterior.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(101,'strength','daily','action','Nordic hamstring curls: 3x5','Kneel with feet anchored, slowly lower your body forward using only hamstring control. 3 sets of 5 reps. Nordic curls reduce hamstring injury risk by 51% in runners.','British Journal of Sports Medicine, 2019',0.0,999.0,1);
INSERT INTO tips VALUES(102,'strength','daily','action','Bulgarian split squat: 3x10','Rear foot elevated on a bench. Lower until your front thigh is parallel. 3x10 per leg with bodyweight or dumbbells. Builds single-leg stability essential for hill running.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(103,'strength','daily','action','Side plank: 3x30s each side','Hold a side plank with your body in a straight line for 30 seconds per side. 3 sets. Hip abductor strength from side planks prevents inward knee collapse that stresses the shin.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(104,'strength','daily','action','Deadlift: 3x8 moderate weight','Perform Romanian deadlifts with moderate weight: 3 sets of 8 reps. Focus on hinging at the hips. Deadlifts strengthen the posterior chain, protecting knees and reducing shin loading.',NULL,20.0,999.0,1);
INSERT INTO tips VALUES(105,'strength','rest_day','action','Gym session: lower body focus','Use rest days for lower body strength: squats, lunges, calf raises, and hip thrusts. 2 gym sessions per week reduces running injury risk by 50%.','Lauersen et al., British Journal of Sports Medicine, 2014',0.0,999.0,1);
INSERT INTO tips VALUES(106,'strength','daily','action','Plank: 3x45s','Hold a forearm plank with glutes and core engaged for 45 seconds. 3 sets. Core stability prevents excessive trunk sway that transmits extra force through the lower legs.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(107,'strength','daily','info','Strength before speed in training','Build a 6-week strength base before adding speed work. Tendons adapt 3-5x slower than muscles. Without structural strength, fast running overloads connective tissue including the tibialis anterior.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(108,'strength','daily','action','Hip abduction: banded walks 3x15','Place a resistance band above your knees. Walk sideways 15 steps each direction, 3 sets. Strong hip abductors prevent knee valgus that increases tibialis anterior strain.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(109,'strength','daily','action','Step-ups: 3x10 each leg','Step onto a 30-40cm box with one foot, drive up without pushing off the floor foot. 3x10 per leg. Step-ups build the eccentric quad control needed for downhill running.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(110,'strength','recovery_day','action','Glute bridges: 3x15 reps','Lie on your back, feet flat, drive hips up squeezing glutes at the top. 3 sets of 15. Weak glutes are the number one cause of compensatory lower leg overload in runners.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(111,'strength','high_load_week','info','Reduce gym intensity this week','During high-volume running weeks, lower gym weights by 20-30% and reduce sets. Heavy lifting competes for recovery resources and can compound running fatigue.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(112,'strength','daily','action','Wall sit: 3x45s','Lean against a wall with thighs parallel to the floor. Hold 45 seconds, 3 sets. Isometric quad strength improves shock absorption on landing, reducing tibialis anterior demand.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(113,'strength','daily','action','Single-leg RDL: 3x8 each','Stand on one leg, hinge forward keeping a flat back, lower a weight toward the ground. 3x8 per leg. Trains balance and posterior chain in a running-specific single-leg pattern.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(114,'strength','rest_day','info','2 strength sessions per week','Research shows 2 strength sessions per week is the minimum effective dose for injury prevention in runners. Schedule them on easy or rest days, not after hard runs.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(115,'form','post_run','info','Check cadence: aim for 170-180','Optimal cadence for most runners is 170-180 steps per minute. Lower cadence means longer ground contact time, which increases tibialis anterior loading. Use a metronome app to check.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(116,'form','daily','info','Land with midfoot, not heel','A midfoot landing under your center of mass reduces braking forces by 30%. Heel striking far ahead of your body forces the tibialis anterior to work harder to control foot slap.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(117,'form','daily','action','Shorten your stride by 5-10%','Overstriding is the most common form error causing tibialis anterior pain. Shorten your stride slightly and increase cadence. You should feel like you are running under yourself.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(118,'form','post_run','info','Lean forward from ankles, not waist','A slight forward lean from the ankles (not the waist) uses gravity to assist forward motion. Leaning from the waist compresses the hip flexors and alters lower leg mechanics.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(119,'form','daily','action','Run strides: 6x100m twice a week','After an easy run, do 6x100m accelerations building to 90% effort. Strides reinforce efficient mechanics at speed without the fatigue of a full interval session.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(120,'form','post_long_run','info','Form breaks down when tired','In the final 5km of long runs, actively focus on maintaining posture and cadence. Fatigue causes heel striking and overpronation that stress the tibialis anterior.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(121,'form','daily','action','Arm swing: elbows at 90 degrees','Keep elbows bent at roughly 90 degrees and swing arms forward-back, not across your body. Cross-body arm swing creates rotational forces that destabilize lower leg mechanics.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(122,'form','daily','info','Relax your feet on the run','Consciously relax your toes and feet mid-run. Gripping the ground with your toes causes the tibialis anterior to stay contracted. Think about running with floppy feet.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(123,'form','post_run','action','Film your running form monthly','Record yourself running from the side and behind once a month. Look for overstriding, heel striking, excessive knee valgus, and trunk sway. Visual feedback accelerates form correction.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(124,'form','daily','info','Eyes forward, head level','Look 15-20 meters ahead, not at your feet. A forward head position increases tension through the entire posterior chain and alters foot strike mechanics.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(125,'form','post_hard_run','info','Pace affects form: slow down','Running faster than your training pace encourages overstriding and heel striking. During easy runs, slow down enough that your form stays relaxed and efficient.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(126,'form','daily','action','High knees drill: 2x20m','Before runs, do 2x20m of high knees with quick ground contact. This drill teaches the hip flexors to lift the leg efficiently, reducing compensatory tibialis anterior recruitment.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(127,'form','daily','info','Quiet feet = efficient running','Listen to your footfall. Loud slapping means the tibialis anterior is losing control of dorsiflexion at impact. Aim for quiet, light landings by pulling your feet under your hips.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(128,'prehab','daily','action','Ankle stability: single-leg balance','Stand on one foot for 30 seconds with eyes open, then 30 seconds with eyes closed. Repeat each side twice. Ankle instability forces the tibialis anterior to overwork as a stabilizer.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(129,'prehab','daily','action','Eccentric calf drops: 3x15','Stand on a step edge on one foot. Rise up on toes, then lower your heel below the step over 3 seconds. 3x15 per leg. Eccentric calf loading prevents Achilles tendinopathy.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(130,'prehab','daily','action','Short foot exercise: 3x10 each','While standing, shorten your foot by pulling the ball of your foot toward your heel without curling toes. Hold 5 seconds, 10 reps. This activates the arch muscles that support the tibialis anterior.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(131,'prehab','recovery_day','action','Full prehab circuit: 15 min','Toe raises (15), calf raises (15), single-leg balance (30s), hip abduction (15), glute bridges (15), ankle circles (20). Do this circuit on every recovery day to maintain structural resilience.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(132,'prehab','daily','info','Tendons need consistent loading','Tendons strengthen through regular, progressive loading over 12+ weeks. Missing prehab sessions for even 2 weeks can reverse 50% of tendon adaptation gains. Consistency beats intensity.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(133,'prehab','daily','action','Peroneal strengthening: 3x12','Loop a band around your forefoot, anchor the other end medially. Evert your foot outward against resistance. 3x12 per foot. Peroneal strength balances the tibialis anterior''s inversion force.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(134,'prehab','high_load_week','warning','Do not skip prehab this week','High-volume weeks are when injuries happen. Maintain your full prehab routine even when tired. Cutting prehab during build weeks is the most common precursor to tibialis anterior flare-ups.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(135,'prehab','daily','action','Towel toe curls: 3x15 each foot','Place a towel flat on the floor. Use your toes to scrunch it toward you, 15 reps per foot. This strengthens intrinsic foot muscles that reduce demand on the tibialis anterior.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(136,'prehab','daily','action','Bosu ball balance: 2x30s each','Stand on a Bosu ball (or folded towel) on one foot for 30 seconds. The unstable surface trains the ankle stabilizers including the tibialis anterior in a functional context.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(137,'prehab','rest_day','action','Toe spacer wear: 30 min daily','Wear toe spacers for 30 minutes daily on rest days. Spreading the toes activates the intrinsic foot muscles and improves forefoot mechanics that reduce tibialis anterior compensation.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(138,'prehab','post_long_run','action','Prehab circuit after long runs','Within 2 hours of your long run, do a gentle prehab set: 10 easy toe raises, 10 ankle circles each way, and 30s single-leg balance each side. Movement prevents post-run stiffness.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(139,'prehab','daily','info','Pain is a signal, not a badge','Sharp or worsening pain in the shin during a run means stop and walk. Continuing through tibialis anterior pain risks stress fractures. Mild soreness after running is acceptable; pain during is not.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(140,'prehab','daily','action','Marble pickups: 20 per foot','Place 20 marbles on the floor and pick them up one at a time with your toes. This builds fine motor control in the foot muscles that share load with the tibialis anterior.',NULL,0.0,999.0,1);
INSERT INTO tips VALUES(141,'prehab','recovery_day','action','Resistance band 4-way ankle: 2x10','Anchor a band and move your foot in dorsiflexion, plantarflexion, inversion, and eversion. 2x10 each direction. Balanced ankle strength prevents compensatory tibialis anterior overload.',NULL,0.0,999.0,1);
