PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      strava_athlete_id TEXT UNIQUE NOT NULL,
      access_token TEXT NOT NULL,
      refresh_token TEXT NOT NULL,
      token_expires_at INTEGER NOT NULL
    );
CREATE TABLE activities (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      strava_id TEXT UNIQUE NOT NULL,
      name TEXT,
      type TEXT,
      distance REAL,
      moving_time INTEGER,
      elapsed_time INTEGER,
      average_speed REAL,
      max_speed REAL,
      average_heartrate REAL,
      max_heartrate REAL,
      total_elevation_gain REAL,
      start_date TEXT,
      suffer_score REAL,
      splits TEXT
    , summary_polyline TEXT, battery_start INTEGER, battery_end INTEGER, shoe_id INTEGER REFERENCES shoes(id));
CREATE TABLE goals (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      type TEXT NOT NULL,
      target_value REAL NOT NULL,
      unit TEXT NOT NULL,
      active INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE training_plans (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      race_name TEXT,
      race_date TEXT NOT NULL,
      race_distance_km REAL NOT NULL,
      start_date TEXT NOT NULL,
      starting_volume_km REAL NOT NULL,
      peak_volume_km REAL,
      total_weeks INTEGER NOT NULL,
      build_increment REAL NOT NULL DEFAULT 0.10,
      recovery_factor REAL NOT NULL DEFAULT 0.70,
      active INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE training_weeks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      plan_id INTEGER NOT NULL REFERENCES training_plans(id) ON DELETE CASCADE,
      week_number INTEGER NOT NULL,
      start_date TEXT NOT NULL,
      target_volume_km REAL NOT NULL,
      phase TEXT NOT NULL,
      cycle_number INTEGER,
      week_in_cycle INTEGER, long_run_km REAL NOT NULL DEFAULT 0, back_to_back INTEGER NOT NULL DEFAULT 0,
      UNIQUE(plan_id, week_number)
    );
CREATE TABLE tips (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      category TEXT NOT NULL,
      trigger TEXT NOT NULL,
      severity TEXT NOT NULL,
      title TEXT NOT NULL,
      body TEXT NOT NULL,
      source TEXT,
      min_weekly_km REAL DEFAULT 0,
      max_weekly_km REAL DEFAULT 999,
      active INTEGER NOT NULL DEFAULT 1
    );
CREATE TABLE tip_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      tip_id INTEGER NOT NULL REFERENCES tips(id),
      shown_date TEXT NOT NULL,
      context TEXT,
      dismissed INTEGER NOT NULL DEFAULT 0,
      UNIQUE(tip_id, shown_date)
    );
CREATE TABLE daily_readiness (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      date TEXT NOT NULL UNIQUE,
      score INTEGER NOT NULL,
      factors TEXT NOT NULL,
      computed_at TEXT NOT NULL
    );
CREATE TABLE shoes (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      type TEXT NOT NULL DEFAULT 'road',
      retired INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    , manual_km REAL NOT NULL DEFAULT 0);
DELETE FROM sqlite_sequence;
COMMIT;
